import { Icon } from "@/registry/erbium/ui/icon";

import { Button } from "@/registry/erbium/ui/button";
import { Kbd } from "@/registry/erbium/ui/kbd";
import { Tooltip, TooltipContent, TooltipTrigger } from "@/registry/erbium/ui/tooltip";

export function TooltipKeyboard() {
  return (
    <Tooltip>
      <TooltipTrigger render={<Button variant="outline" size="icon-sm" />}>
        <Icon name="save" />
      </TooltipTrigger>
      <TooltipContent>
        Save Changes <Kbd hotkey="S" />
      </TooltipContent>
    </Tooltip>
  );
}
